from solution import change_base
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# Reference model written directly from spec (obviously correct)
def ref_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))


def test_example_8_base_3():
    assert change_base(8, 3) == "22"


def test_example_8_base_2():
    assert change_base(8, 2) == "1000"


def test_example_7_base_2():
    assert change_base(7, 2) == "111"


def test_zero_returns_zero_string():
    assert change_base(0, 2) == "0"


@given(base=st.integers(min_value=2, max_value=9))
def test_zero_for_all_bases(base):
    assert change_base(0, base) == "0"


@given(x=st.integers(min_value=0, max_value=10_000), base=st.integers(min_value=2, max_value=9))
def test_roundtrip_value_preserved(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    assert s != ""
    assert int(s, base) == x


@given(x=st.integers(min_value=0, max_value=10_000), base=st.integers(min_value=2, max_value=9))
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == ref_change_base(x, base)


@given(x=st.integers(min_value=0, max_value=10_000), base=st.integers(min_value=2, max_value=9))
def test_digits_are_valid_for_base(x, base):
    s = change_base(x, base)
    assert len(s) >= 1
    allowed = set(str(d) for d in range(base))
    assert set(s) <= allowed
    assert all(c.isdigit() for c in s)


@given(x=st.integers(min_value=1, max_value=10_000), base=st.integers(min_value=2, max_value=9))
def test_no_leading_zeros_for_positive(x, base):
    s = change_base(x, base)
    assert s[0] != "0"


@given(base=st.integers(min_value=2, max_value=9), d=st.integers(min_value=0, max_value=8))
def test_single_digit_identity(base, d):
    assume(d < base)
    assert change_base(d, base) == str(d)


@given(base=st.integers(min_value=2, max_value=9), k=st.integers(min_value=1, max_value=6))
def test_base_power_is_one_followed_by_zeros(base, k):
    assert change_base(base ** k, base) == "1" + "0" * k


@given(base=st.integers(min_value=2, max_value=9), k=st.integers(min_value=1, max_value=6))
def test_base_power_minus_one_is_all_max_digits(base, k):
    assert change_base(base ** k - 1, base) == str(base - 1) * k


@given(x=st.integers(min_value=0, max_value=10_000), base=st.integers(min_value=2, max_value=9))
def test_most_significant_digit_nonzero_and_length_matches(x, base):
    s = change_base(x, base)
    # length must equal number of base-digits of x
    if x == 0:
        assert s == "0"
    else:
        # s must not have extra leading digit
        assert int(s[0]) >= 1
        # removing leading digit must drop value below base^(len-1)
        assert int(s, base) >= base ** (len(s) - 1)
        assert int(s, base) < base ** len(s)


@given(x=st.integers(min_value=2, max_value=500), base=st.integers(min_value=2, max_value=9))
def test_appending_zero_digit_multiplies_by_base(x, base):
    # metamorphic: representation of x*base is representation of x + "0"
    assert change_base(x * base, base) == change_base(x, base) + "0"


@given(x=st.integers(min_value=0, max_value=5000), base=st.integers(min_value=2, max_value=9))
def test_last_digit_equals_remainder(x, base):
    s = change_base(x, base)
    assert s[-1] == str(x % base)


@given(x=st.integers(min_value=0, max_value=5000), base=st.integers(min_value=2, max_value=9))
def test_prefix_equals_quotient_representation(x, base):
    # metamorphic: dropping last digit gives representation of x // base (except x < base)
    s = change_base(x, base)
    if x >= base:
        assert s[:-1] == change_base(x // base, base)
    else:
        assert len(s) == 1
